		}
	} else if variant == fyne.VariantLight {
		if c, ok := t.colorsLight[name]; ok {
			return c
		}
	}

	// Check generic colors
	if c, ok := t.colors[name]; ok {
		return c
	}

	// Fall back to default theme
	return DarkTheme().Color(name, variant)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if icon, ok := t.icons[name]; ok {
		return icon
	}
	return DarkTheme().Icon(name)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	var key string
	if style.Monospace {
		key = "monospace"
	} else if style.Bold && style.Italic {
		key = "boldItalic"
	} else if style.Bold {
		key = "bold"
	} else {
		key = "regular"
	}

	if font, ok := t.fonts[key]; ok {
		return font
	}
	return DarkTheme().Font(style)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if size, ok := t.sizes[name]; ok {
		return size
	}
	return DarkTheme().Size(name)
}

