// Add appends the specified object to the items this container manages.
// If the object is nil, this is a no-op.
//
// Since: 1.4
func (c *Container) Add(add CanvasObject) {
	if add == nil {
		return
	}
	c.Objects = append(c.Objects, add)
	c.layout()
}

// RemoveAll removes all objects from the container.
//
// Since: 2.1
func (c *Container) RemoveAll() {
	c.Objects = nil
	c.layout()
}

