package validation

import (
	"errors"
	"unicode"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a new validator that checks if all characters in the string are letters.
// The validator will return nil if all characters are letters (using unicode.IsLetter),
// otherwise returns an error.
//
// Since: 2.1
func NewAllStrings() fyne.StringValidator {
	return func(text string) error {
		if text == "" {
			return nil // Empty string is valid
		}

		for _, r := range text {
			if !unicode.IsLetter(r) {
				return errors.New("input must contain only letters")
			}
		}

		return nil
	}
}

package validation

import (
	"errors"
	"unicode"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a new validator that checks if all characters in the string are letters.
// The validator will return nil if all characters are letters (using unicode.IsLetter),
// otherwise returns an error.
//
// Since: 2.1
func NewAllStrings() fyne.StringValidator {
	return func(text string) error {
		if text == "" {
			return nil // Empty string is valid
		}

		for _, r := range text {
			if !unicode.IsLetter(r) {
				return errors.New("input must contain only letters")
			}
		}

		return nil
	}
}

